-- Bootstrap the demo catalog once. Keep existing CMS content intact.
create table if not exists demo_seeds (
  name text primary key
);

do $seed$
begin
  lock table screens in share row exclusive mode;

  insert into demo_seeds (name) values ('screens')
  on conflict do nothing;

  if not found or exists (select 1 from screens) then
    return;
  end if;

  with seeded as (
    insert into screens (
      id, name, description, rainbow_source, revision, created_at, updated_at, is_root, version
    )
    select id, name, description, rainbow_source, revision, created_at, updated_at, is_root, version
    from jsonb_populate_recordset(null::screens, $screen_snapshot$
