    "description": "Carrinho apresentado em modal pela Loja",
    "rainbow_source": "use Screen@1.0.0\nuse VerticalStack@1.0.0\nuse HorizontalStack@1.0.0\nuse Text@1.0.0\nuse Badge@1.0.0\nuse Avatar@1.0.0\nuse Card@1.0.0\nuse Button@1.0.0\nuse Alert@1.0.0\nuse ForEach@1.0.0\nuse ShowSuccessEvent@1.0.0\nuse ClearListEvent@1.0.0\nuse BackNavigationEvent@1.0.0\n\nScreen(\n  navigationBar: (\n    title: \"Carrinho\",\n    leading: \"none\",\n    trailing: \"close\"\n  ),\n  scroll: (\n    enabled: true,\n    isLazy: true\n  )\n) {\n  VerticalStack(\n    alignment: .leading,\n    spacing: 12\n  ) {\n    Text(\n      text: \"Seu carrinho\",\n      style: \"xl\",\n      weight: \"semibold\",\n      color: \"foreground\"\n    )\n\n    Text(\n      text: \"Os produtos adicionados na Loja aparecem aqui. A lista é compartilhada entre as telas do app.\",\n      style: \"sm\",\n      weight: \"regular\",\n      color: \"mutedForeground\"\n    )\n\n    ForEach(\n      source: \"cart\",\n      spacing: 12\n    ) {\n      Card {\n        HorizontalStack(\n          alignment: .center,\n          spacing: 16\n        ) {\n          Avatar(\n            initials: \"?\",\n            size: \"lg\",\n            imageURL: \"{{thumbnail}}\"\n          )\n\n          VerticalStack(\n            alignment: .leading,\n            spacing: 6\n          ) {\n            Text(\n              text: \"{{title}}\",\n              style: \"base\",\n              weight: \"semibold\",\n              color: \"foreground\"\n            )\n\n            Badge(\n              text: \"{{category}}\",\n              variant: \"secondary\"\n            )\n\n            Text(\n              text: \"US$ {{price|number:2}}\",\n              style: \"sm\",\n              weight: \"medium\",\n              color: \"foreground\"\n            )\n          }\n        }\n      }\n    }\n\n    Alert(\n      title: \"Compra simulada\",\n      message: \"Nenhum pagamento é feito: o botão abaixo só demonstra o fluxo.\",\n      variant: \"default\"\n    )\n\n    Button(\n      title: \"Simular compra\",\n      icon: \"credit-card\",\n      variant: \"default\",\n      size: \"lg\",\n      isEnabled: true\n    )\n    .events {\n      OnTap {\n        ShowSuccessEvent(\n          title: \"Compra realizada!\",\n          message: \"Seu pedido foi simulado com sucesso.\"\n        )\n        ClearListEvent(listID: \"cart\")\n        BackNavigationEvent()\n      }\n    }\n  }\n}"
  },
  {
    "id": "2d0b796f-4e26-4e17-9a72-7795147228bc",
