    "description": "Experiência de e-commerce profissional: catálogo filtrável, cards e DummyJSON.",
    "rainbow_source": "use Screen@1.0.0\nuse VerticalStack@1.0.0\nuse HorizontalStack@1.0.0\nuse Text@1.0.0\nuse Badge@1.0.0\nuse Avatar@1.0.0\nuse Card@1.0.0\nuse Separator@1.0.0\nuse ForEach@1.0.0\nuse SearchBar@1.0.0\nuse UpdateListEvent@1.0.0\nuse Button@1.0.0\nuse FloatingButton@1.0.0\nuse AddListItemEvent@1.0.0\nuse ShowToastEvent@1.0.0\nuse NavigateEvent@1.0.0\n\nScreen(\n  navigationBar: (\n    title: \"Loja\",\n    theme: \"blue\",\n    leading: \"auto\"\n  ),\n  scroll: (\n    enabled: true,\n    isLazy: true,\n    fastRefresh: true\n  )\n) {\n  VerticalStack(\n    alignment: .leading,\n    spacing: 12\n  ) {\n    Text(\n      text: \"Catálogo de produtos\",\n      style: \"xl\",\n      weight: \"semibold\",\n      color: \"foreground\"\n    )\n\n    Text(\n      text: \"Produtos da DummyJSON com fotos, renderizados por um template Rainbow.\",\n      style: \"sm\",\n      weight: \"regular\",\n      color: \"mutedForeground\"\n    )\n\n    ForEach(\n      source: \"products\",\n      spacing: 12\n    ) {\n      Card {\n        HorizontalStack(\n          alignment: .center,\n          spacing: 16\n        ) {\n          Avatar(\n            initials: \"{{brand|default:?}}\",\n            size: \"xl\",\n            imageURL: \"{{thumbnail}}\"\n          )\n\n          VerticalStack(\n            alignment: .leading,\n            spacing: 6\n          ) {\n            Text(\n              text: \"{{title}}\",\n              style: \"lg\",\n              weight: \"semibold\",\n              color: \"foreground\"\n            )\n\n            Badge(\n              text: \"{{category}}\",\n              variant: \"default\"\n            )\n\n            Text(\n              text: \"US$ {{price|number:2}} · {{stock}} em estoque · ★ {{rating|number:1}}\",\n              style: \"xs\",\n              weight: \"regular\",\n              color: \"mutedForeground\"\n            )\n\n            Button(\n              title: \"Adicionar ao carrinho\",\n              icon: \"shopping-cart\",\n              variant: \"secondary\",\n              size: \"sm\",\n              isEnabled: true\n            )\n            .events {\n              OnTap {\n                AddListItemEvent(\n                  listID: \"cart\",\n                  item: (\n                    id: \"{{id}}\",\n                    title: \"{{title}}\",\n                    price: \"{{price}}\",\n                    thumbnail: \"{{thumbnail}}\",\n                    category: \"{{category}}\"\n                  )\n                )\n                ShowToastEvent(\n                  title: \"Adicionado ao carrinho\",\n                  message: \"{{title}}\",\n                  icon: \"circle-check\",\n                  variant: \"success\"\n                )\n              }\n            }\n          }\n        }\n      }\n    }\n\n    Separator()\n\n    Text(\n      text: \"Role até o fim para carregar mais produtos.\",\n      style: \"xs\",\n      weight: \"regular\",\n      color: \"mutedForeground\"\n    )\n  }\n}\n.events {\n  OnAppear {\n    UpdateListEvent(\n      listID: \"products\",\n      url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n      itemsPath: \"products\",\n      pageSize: 6,\n      offsetParameter: \"skip\",\n      totalPath: \"total\",\n      maxPages: 5\n    )\n  }\n  OnScrollEndReached {\n    UpdateListEvent(\n      listID: \"products\",\n      url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n      itemsPath: \"products\",\n      pageSize: 6,\n      offsetParameter: \"skip\",\n      totalPath: \"total\",\n      maxPages: 5\n    )\n  }\n}\n.slots {\n  FloatingButton {\n    FloatingButton(\n      icon: \"shopping-cart\",\n      badgeList: \"cart\"\n    )\n    .events {\n      OnTap {\n        NavigateEvent(\n          screenName: \"cart\",\n          presentation: \"modal\"\n        )\n      }\n    }\n  }\n  SearchBar {\n    SearchBar(placeholder: \"Buscar produtos\")\n    .id(\"product-search\")\n    .events {\n      OnSubmit {\n        UpdateListEvent(\n          listID: \"products\",\n          url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n          itemsPath: \"products\",\n          mode: \"replace\",\n          pageSize: 6,\n          offsetParameter: \"skip\",\n          totalPath: \"total\",\n          maxPages: 5\n        )\n      }\n    }\n    .slots {\n      Badges {\n        Badge(\n          text: \"Todos\",\n          variant: \"secondary\",\n          input: \"product-category\",\n          value: \"\",\n          selectedVariant: \"default\"\n        )\n        .events {\n          OnTap {\n            UpdateListEvent(\n              mode: \"replace\",\n              listID: \"products\",\n              url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n              itemsPath: \"products\",\n              pageSize: 6,\n              offsetParameter: \"skip\",\n              totalPath: \"total\",\n              maxPages: 5\n            )\n          }\n        }\n        Badge(\n          text: \"Beauty\",\n          variant: \"secondary\",\n          input: \"product-category\",\n          value: \"category/beauty\",\n          selectedVariant: \"default\"\n        )\n        .events {\n          OnTap {\n            UpdateListEvent(\n              mode: \"replace\",\n              listID: \"products\",\n              url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n              itemsPath: \"products\",\n              pageSize: 6,\n              offsetParameter: \"skip\",\n              totalPath: \"total\",\n              maxPages: 5\n            )\n          }\n        }\n        Badge(\n          text: \"Fragrances\",\n          variant: \"secondary\",\n          input: \"product-category\",\n          value: \"category/fragrances\",\n          selectedVariant: \"default\"\n        )\n        .events {\n          OnTap {\n            UpdateListEvent(\n              mode: \"replace\",\n              listID: \"products\",\n              url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n              itemsPath: \"products\",\n              pageSize: 6,\n              offsetParameter: \"skip\",\n              totalPath: \"total\",\n              maxPages: 5\n            )\n          }\n        }\n        Badge(\n          text: \"Furniture\",\n          variant: \"secondary\",\n          input: \"product-category\",\n          value: \"category/furniture\",\n          selectedVariant: \"default\"\n        )\n        .events {\n          OnTap {\n            UpdateListEvent(\n              mode: \"replace\",\n              listID: \"products\",\n              url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n              itemsPath: \"products\",\n              pageSize: 6,\n              offsetParameter: \"skip\",\n              totalPath: \"total\",\n              maxPages: 5\n            )\n          }\n        }\n        Badge(\n          text: \"Groceries\",\n          variant: \"secondary\",\n          input: \"product-category\",\n          value: \"category/groceries\",\n          selectedVariant: \"default\"\n        )\n        .events {\n          OnTap {\n            UpdateListEvent(\n              mode: \"replace\",\n              listID: \"products\",\n              url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n              itemsPath: \"products\",\n              pageSize: 6,\n              offsetParameter: \"skip\",\n              totalPath: \"total\",\n              maxPages: 5\n            )\n          }\n        }\n        Badge(\n    