talPath: \"total\",\n              maxPages: 5\n            )\n          }\n        }\n        Badge(\n          text: \"Smartphones\",\n          variant: \"secondary\",\n          input: \"product-category\",\n          value: \"category/smartphones\",\n          selectedVariant: \"default\"\n        )\n        .events {\n          OnTap {\n            UpdateListEvent(\n              mode: \"replace\",\n              listID: \"products\",\n              url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n              itemsPath: \"products\",\n              pageSize: 6,\n              offsetParameter: \"skip\",\n              totalPath: \"total\",\n              maxPages: 5\n            )\n          }\n        }\n        Badge(\n          text: \"Tablets\",\n          variant: \"secondary\",\n          input: \"product-category\",\n          value: \"category/tablets\",\n          selectedVariant: \"default\"\n        )\n        .events {\n          OnTap {\n            UpdateListEvent(\n              mode: \"replace\",\n              listID: \"products\",\n              url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n              itemsPath: \"products\",\n              pageSize: 6,\n              offsetParameter: \"skip\",\n              totalPath: \"total\",\n              maxPages: 5\n            )\n          }\n        }\n        Badge(\n          text: \"Mobile accessories\",\n          variant: \"secondary\",\n          input: \"product-category\",\n          value: \"category/mobile-accessories\",\n          selectedVariant: \"default\"\n        )\n        .events {\n          OnTap {\n            UpdateListEvent(\n              mode: \"replace\",\n              listID: \"products\",\n              url: \"https://dummyjson.com/products/{{input.product-category|default:search}}?q={{input.product-search}}\",\n              itemsPath: \"pr