  {
    "id": "70cb142f-d2d4-4b18-b843-4f218ac2bb2f",
    "name": "home",
    "is_root": true,
    "version": "1.0.30",
    "revision": 32,
    "created_at": "2026-11-07T19:56:39.277841+00:00",
    "updated_at": "2026-11-22T21:34:11.075593+00:00",
    "description": "Home profissional do showcase com Pokédex, loja, formulário e fluxo CMS → Rainbow → app.",
    "rainbow_source": "use Screen@1.0.0\nuse TabBar@1.0.0\nuse Tab@1.0.0\nuse VerticalStack@1.0.0\nuse HorizontalStack@1.0.0\nuse Text@1.0.0\nuse Badge@1.0.0\nuse Avatar@1.0.0\nuse Card@1.0.0\nuse Button@1.0.0\nuse Separator@1.0.0\nuse Sheet@1.0.0\nuse ChangeTabEvent@1.0.0\nuse OpenBottomSheetEvent@1.0.0\nuse CloseBottomSheetEvent@1.0.0\n\nScreen(\n  navigationBar: (\n    title: \"NShiftUI Showcase\",\n    theme: \"green\",\n    leading: \"auto\"\n  ),\n  scroll: (\n    enabled: true,\n    fastRefresh: true\n  )\n) {\n  VerticalStack(\n    alignment: .leading,\n    spacing: 12\n  ) {\n    Text(\n      text: \"SDUI + RAINBOW\",\n      style: \"sm\",\n      weight: \"semibold\",\n      color: \"primary\"\n    )\n\n    Text(\n      text: \"Experiências nativas, publicadas pelo CMS.\",\n      style: \"xl\",\n      weight: \"semibold\",\n      color: \"foreground\"\n    )\n\n    Text(\n      text: \"Uma base mobile que muda sem precisar publicar uma nova versão do app.\",\n      style: \"base\",\n      weight: \"regular\",\n      color: \"mutedForeground\"\n    )\n\n    HorizontalStack(\n      alignment: .center,\n      spacing: 8\n    ) {\n      Badge(\n        text: \"CMS\",\n        variant: \"default\"\n      )\n\n      Badge(\n        text: \"Rainbow\",\n        variant: \"secondary\"\n      )\n\n      Badge(\n        text: \"iOS + Android\",\n        variant: \"outline\"\n      )\n    }\n\n    Card {\n      HorizontalStack(\n        alignment: .center,\n        spacing: 16\n      ) {\n        Avatar(\n          initials: \"025\",\n          size: \"lg\",\n          imageURL: \"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/25.png\"\n        )\n\n        VerticalStack(\n          alignment: .leading,\n          spacing: 6\n        ) {\n          Text(\n            text: \"Pokédex\",\n            style: \"lg\",\n            weight: \"semibold\",\n            color: \"foreground\"\n          )\n\n          Text(\n            text: \"Fotos oficiais, detalhes e dados da PokeAPI.\",\n            style: \"sm\",\n            weight: \"regular\",\n            color: \"mutedForeground\"\n          )\n\n          Button(\n            title: \"Explorar Pokédex\",\n            icon: \"\",\n            variant: \"default\",\n            size: \"sm\",\n            isEnabled: true\n          )\n          .events {\n            OnTap {\n              ChangeTabEvent(index: 1)\n            }\n          }\n        }\n      }\n    }\n\n    Card {\n      HorizontalStack(\n        alignment: .center,\n        spacing: 16\n      ) {\n        Avatar(\n          initials: \"LOJA\",\n          size: \"lg\",\n          imageURL: \"https://cdn.dummyjson.com/product-images/womens-bags/prada-women-bag/thumbnail.webp\"\n        )\n\n        VerticalStack(\n          alignment: .leading,\n          spacing: 6\n        ) {\n          Text(\n            text: \"Loja\",\n            style: \"lg\",\n            weight: \"semibold\",\n            color: \"foreground\"\n          )\n\n          Text(\n            text: \"Catálogo, filtro e chamada ao DummyJSON.\",\n            style: \"sm\",\n            weight: \"regular\",\n            color: \"mutedForeground\"\n          )\n\n          Button(\n            title: \"Explorar loja\",\n            icon: \"\",\n            variant: \"secondary\",\n            size: \"sm\",\n            isEnabled: true\n          )\n          .events {\n            OnTap {\n              ChangeTabEvent(index: 2)\n            }\n          }\n        }\n      }\n    }\n\n    Separator()\n\n    Button(\n      title: \"Como o fluxo funciona\",\n      icon: \"\",\n      variant: \"ghost\",\n      size: \"default\",\n      isEnabled: true\n    )\n    .events {\n      OnTap {\n        OpenBottomSheetEvent(sheetID: \"showcase-flow\")\n      }\n    }\n  }\n}\n.slots {\n  TabBar {\n    TabBar {\n      Tab(\n        title: \"Início\",\n        icon: \"house\"\n      )\n\n      Tab(\n        title: \"Pokédex\",\n        icon: \"search\",\n        route: \"pokedex\"\n      )\n\n      Tab(\n        title: \"Loja\",\n        icon: \"layout-grid\",\n        route: \"catalog\"\n      )\n\n      Tab(\n        title: \"Ajustes\",\n        icon: \"settings\",\n        route: \"settings\"\n      )\n    }\n  }\n  BottomSheet {\n    Sheet(title: \"Do CMS ao app\") {\n      Text(\n        text: \"1. A tela é composta no CMS.\",\n        style: \"base\",\n        weight: \"regular\",\n        color: \"foreground\"\n      )\n\n      Text(\n        text: \"2. O CMS publica o documento Rainbow.\",\n        style: \"base\",\n        weight: \"regular\",\n        color: \"foreground\"\n      )\n\n      Text(\n        text: \"3. iOS e Android buscam o documento e renderizam componentes nativos.\",\n        style: \"base\",\n        weight: \"regular\",\n        color: \"foreground\"\n      )\n\n      Button(\n        title: \"Fechar\",\n        icon: \"\",\n        variant: \"secondary\",\n        size: \"default\",\n        isEnabled: true\n      )\n      .events {\n        OnTap {\n          CloseBottomSheetEvent(sheetID: \"showcase-flow\")\n        }\n      }\n    }\n    .id(\"showcase-flow\")\n  }\n}"
  },
  {
    "id": "0f2228d2-4169-4e5d-913a-2aa33c512804",
    "name": "pokedex",
    "is_root": false,
    "version": "1.0.11",
    "revision": 12,
    "created_at": "2026-11-22T03:29:01.651064+00:00",
    "updated_at": "2026-11-22T21:03:43.488942+00:00",
    "description": "Pokédex visual com fotos oficiais, detalhes navegáveis e paginação real por fim do scroll via PokeAPI.",
    "rainbow_source": "use Screen@1.0.0\nuse VerticalStack@1.0.0\nuse HorizontalStack@1.0.0\nuse Text@1.0.0\nuse Badge@1.0.0\nuse Avatar@1.0.0\nuse Card@1.0.0\nuse Button@1.0.0\nuse Separator@1.0.0\nuse Sheet@1.0.0\nuse ForEach@1.0.0\nuse SearchBar@1.0.0\nuse UpdateListEvent@1.0.0\nuse OpenBottomSheetEvent@1.0.0\nuse CloseBottomSheetEvent@1.0.0\nuse NavigateEvent@1.0.0\n\nScreen(\n  navigationBar: (\n    title: \"Pokédex\",\n    theme: \"red\",\n    leading: \"auto\"\n  ),\n  scroll: (\n    enabled: true,\n    isLazy: true,\n    fastRefresh: true,\n    header: {\n      VerticalStack(\n        alignment: .leading,\n        spacing: 4\n      ) {\n        Text(\n          text: \"COLEÇÃO ORIGINAL\",\n          style: \"xs\",\n          weight: \"semibold\",\n          color: \"primary\"\n        )\n\n        Text(\n          text: \"Encontre seu próximo favorito.\",\n          style: \"xl\",\n          weight: \"semibold\",\n          color: \"foreground\"\n        )\n\n        Text(\n          text: \"Fotos oficiais, tipos e detalhes carregados da PokeAPI e renderizados por um template Rainbow.\",\n          style: \"sm\",\n          weight: \"regular\",\n          color: \"mutedForeground\"\n        )\n      }\n    },\n    footer: {\n      Text(\n        text: \"Dados de referência: PokeAPI · Conteúdo controlado por Rainbow.\",\n        style: \"xs\",\n        weight: \"regular\",\n        color: \"mutedForeground\"\n      )\n    }\n  )\n) {\n  VerticalStack(\n    alignment: .leading,\n    spacing: 12\n  ) {\n    HorizontalStack(\n      alignment: .center,\n      spacing: 8\n    ) {\n      Badge(\n        text: \"API pública\",\n        variant: \"default\"\n      )\n\n      Badge(\n        text: \"Fotos oficiais\",\n        variant: \"secondary\"\n      )\n\n      Badge(\n        text: \"List nativa\",\n        variant: \"outline\"\n      )\n    }\n\n    ForEach(\n      source: \"pokemon\",\n      spacing: 12,\n      searchInput: \"pokemon-search\",\n      searchPath: \"name\"\n    ) {\n      Card {\n        HorizontalStack(\n          alignment: .center,\n          spacing: 16\n        ) {\n          Avatar(\n            initials: \"{{id|pad:3}}\",\n            size: \"xl\",\n            imageURL: \"{{sprites.other.official-artwork.front_default}}\"\n          )\n\n          VerticalStack(\n            alignment: .leading,\n            spacing: 6\n          ) {\n            Text(\n              text: \"{{name|capitalize}}\",\n              style: \"lg\",\n              weight: \"semibold\",\n              color: \"foreground\"\n            )\n\n            Badge(\n              text: \"{{types|map:type.name|join: · }}\",\n              variant: \"default\"\n            )\n\n            Text(\n              text: \"#{{id|pad:3}} · PokeAPI\",\n              style: \"xs\",\n              weight: \"regular\",\n              color: \"mutedForeground\"\n            )\n          }\n        }\n      }\n      .events {\n        OnTap {\n          NavigateEvent(\n            screenName: \"pokemon-details\",\n            parameters: (id: \"{{id}}\")\n          )\n        }\n      }\n    }\n\n    Separator()\n\n    Button(\n      title: \"Como esta experiência foi criada\",\n      icon: \"\",\n      variant: \"ghost\",\n      size: \"default\",\n      isEnabled: true\n    )\n    .events {\n      OnTap {\n        OpenBottomSheetEvent(sheetID: \"pokedex-info\")\n      }\n    }\n  }\n}\n.events {\n  OnAppear {\n    UpdateListEvent(\n      listID: \"pokemon\",\n      url: \"https://pokeapi.co/api/v2/pokemon\",\n      itemsPath: \"results\",\n      pageSize: 6,\n      nextPath: \"next\",\n      expandPath: \"url\"\n    )\n  }\n  OnScrollEndReached {\n    UpdateListEvent(\n      listID: \"pokemon\",\n      url: \"https://pokeapi.co/api/v2/pokemon\",\n      itemsPath: \"results\",\n      pageSize: 6,\n      nextPath: \"next\",\n      expandPath: \"url\",\n      maxPages: 3\n    )\n  }\n}\n.slots {\n  SearchBar {\n    SearchBar(placeholder: \"Buscar Pokémon\")\n    .id(\"pokemon-search\")\n    .events {\n      OnChange {\n        UpdateListEvent(\n          listID: \"pokemon\",\n          url: \"https://pokeapi.co/api/v2/pokemon\",\n          itemsPath: \"results\",\n          pageSize: 6,\n          nextPath: \"next\",\n          expandPath: \"url\",\n          maxPages: 5\n        )\n      }\n    }\n  }\n  BottomSheet {\n    Sheet(title: \"Pokédex + Rainbow\") {\n      Text(\n        text: \"Nenhum card é fixo: o ForEach repete o template Rainbow para cada item que o UpdateListEvent carrega da PokeAPI.\",\n        style: \"base\",\n        weight: \"regular\",\n        color: \"foreground\"\n      )\n\n      Text(\n        text: \"OnAppear carrega a primeira página e OnScrollEndReached as próximas.\",\n        style: \"sm\",\n        weight: \"regular\",\n        color: \"mutedForeground\"\n      )\n\n      Button(\n        title: \"Fechar\",\n        icon: \"\",\n        variant: \"secondary\",\n        size: \"default\",\n        isEnabled: true\n      )\n      .events {\n        OnTap {\n          CloseBottomSheetEvent(sheetID: \"pokedex-info\")\n        }\n      }\n    }\n    .id(\"pokedex-info\")\n  }\n}"
  },
  {
    "id": "a29676c3-5c9e-4b6c-9355-b09ed73b517a",
    "name": "pokemon-details",
    "is_root": false,
    "version": "1.0.1",
    "revision": 2,
    "created_at": "2026-11-22T06:48:21.174151+00:00",
    "updated_at": "2026-11-22T20:15:36.800774+00:00",
    "description": "Template genérico de detalhes com contexto de rota e dados da PokeAPI.",
    "rainbow_source": "use Screen@1.0.0\nuse VerticalStack@1.0.0\nuse HorizontalStack@1.0.0\nuse Text@1.0.0\nuse Badge@1.0.0\nuse Avatar@1.0.0\nuse Card@1.0.0\nuse Button@1.0.0\nuse ForEach@1.0.0\nuse UpdateListEvent@1.0.0\nuse BackNavigationEvent@1.0.0\n\nScreen(\n  navigationBar: (\n    title: \"Detalhes\",\n    theme: \"yellow\",\n    leading: \"back\"\n  ),\n  scroll: (enabled: true)\n) {\n  VerticalStack(\n    alignment: .leading,\n    spacing: 12\n  ) {\n    ForEach(\n      source: \"pokemon\",\n      spacing: 12\n    ) {\n      HorizontalStack(\n        alignment: .center,\n        spacing: 16\n      ) {\n        Avatar(\n          initials: \"{{id|pad:3}}\",\n          size: \"xl\",\n          imageURL: \"{{sprites.other.official-artwork.front_default}}\"\n        )\n\n        VerticalStack(\n          alignment: .leading,\n          spacing: 4\n        ) {\n          Text(\n            text: \"{{name|capitalize}}\",\n            style: \"xl\",\n            weight: \"semibold\",\n            color: \"foreground\"\n          )\n\n          Text(\n            text: \"Pokémon #{{id|pad:3}}\",\n            style: \"sm\",\n            weight: \"regular\",\n            color: \"mutedForeground\"\n          )\n\n          Badge(\n            text: \"{{types|map:type.name|join: · }}\",\n            variant: \"default\"\n          )\n        }\n      }\n\n      Card {\n        Text(\n          text: \"Atributos\",\n          style: \"lg\",\n          weight: \"semibold\",\n          color: \"foreground\"\n        )\n\n        Text(\n          text: \"Altura {{height|divide:10|number:1}} m · Peso {{weight|divide:10|number:1}} kg\",\n          style: \"sm\",\n          weight: \"regular\",\n          color: \"mutedForeground\"\n        )\n\n        Text(\n          text: \"HP {{stats.0.base_stat}} · Ataque {{stats.1.base_stat}} · Defesa {{stats.2.base_stat}} · Velocidade {{stats.5.base_stat}}\",\n          style: \"sm\",\n          weight: \"regular\",\n          color: \"mutedForeground\"\n        )\n      }\n\n      Card {\n        Text(\n          text: \"Habilidades\",\n          style: \"lg\",\n          weight: \"semibold\",\n          color: \"foreground\"\n        )\n\n        Text(\n          text: \"{{abilities|map:ability.name|join:, }}\",\n          style: \"sm\",\n          weight: \"regular\",\n          color: \"mutedForeground\"\n        )\n      }\n    }\n\n    Button(\n      title: \"Voltar para a Pokédex\",\n      icon: \"\",\n      variant: \"secondary\",\n      size: \"default\",\n      isEnabled: true\n    )\n    .events {\n      OnTap {\n        BackNavigationEvent()\n      }\n    }\n  }\n}\n.events {\n  OnAppear {\n    UpdateListEvent(\n      listID: \"pokemon\",\n      url: \"https://pokeapi.co/api/v2/pokemon/{{route.id}}\",\n      mode: \"replace\"\n    )\n  }\n}"
  },
  {
    "id": "498317d0-b82d-4f2b-a63a-f4810275e03d",
    "name": "references",
