    "description": "Referências, inspirações e SDKs da POC",
    "rainbow_source": "use Screen@1.0.0\nuse VerticalStack@1.0.0\nuse Text@1.0.0\nuse Card@1.0.0\nuse Item@1.0.0\n\nScreen(\n  navigationBar: (\n    title: \"Referências\",\n    leading: \"auto\"\n  ),\n  scroll: (\n    enabled: true,\n    fastRefresh: true\n  )\n) {\n  VerticalStack(\n    alignment: .leading,\n    spacing: 16\n  ) {\n    Text(\n      text: \"Inspirações e SDKs\",\n      style: \"xl\",\n      weight: \"semibold\",\n      color: \"foreground\"\n    )\n\n    Text(\n      text: \"Tudo o que a POC usa no iOS, no Android, no CMS e no backend.\",\n      style: \"sm\",\n      weight: \"regular\",\n      color: \"mutedForeground\"\n    )\n\n    Text(\n      text: \"INSPIRAÇÃO\",\n      style: \"xs\",\n      weight: \"semibold\",\n      color: \"primary\"\n    )\n\n    Card {\n      Item(\n        title: \"shadcn/ui\",\n        subtitle: \"Base do design system SCN: tokens, componentes e temas\",\n        initials: \"UI\"\n      )\n\n      Item(\n        title: \"Sonner\",\n        subtitle: \"Cores de feedback dos toasts (richColors)\",\n        initials: \"SO\"\n      )\n\n      Item(\n        title: \"Lucide\",\n        subtitle: \"Ícones usados no app e no CMS\",\n        initials: \"LU\"\n      )\n    }\n\n    Text(\n      text: \"iOS\",\n      style: \"xs\",\n      weight: \"semibold\",\n      color: \"primary\"\n    )\n\n    Card {\n      Item(\n        title: \"SwiftUI e UIKit\",\n        subtitle: \"Interface nativa e barra de navegação Liquid Glass\",\n        initials: \"SW\"\n      )\n\n      Item(\n        title: \"WebKit\",\n        subtitle: \"WKWebView do container WebView\",\n        initials: \"WK\"\n      )\n\n      Item(\n        title: \"NShiftUI-iOS\",\n        subtitle: \"Engine SDUI: plugins, eventos e compilador Rainbow\",\n        initials: \"NS\"\n      )\n\n      Item(\n        title: \"RainbowParser-iOS 0.2.0-beta.1\",\n        subtitle: \"Parser da linguagem Rainbow\",\n        initials: \"RP\"\n      )\n\n      Item(\n        title: \"Swinject 2.10.0\",\n        subtitle: \"Injeção de dependências\",\n        initials: \"SJ\"\n      )\n\n      Item(\n        title: \"Alamofire 5.12.2\",\n        subtitle: \"Requisições HTTP\",\n        initials: \"AF\"\n      )\n\n      Item(\n        title: \"swift-syntax 603.0.2\",\n        subtitle: \"Macros dos plugins e eventos\",\n        initials: \"SX\"\n      )\n    }\n\n    Text(\n      text: \"ANDROID\",\n      style: \"xs\",\n      weight: \"semibold\",\n      color: \"primary\"\n    )\n\n    Card {\n      Item(\n        title: \"Jetpack Compose BOM 2026.09.00\",\n        subtitle: \"UI declarativa com Material 3\",\n        initials: \"JC\"\n      )\n\n      Item(\n        title: \"Kotlin 2.4.20\",\n        subtitle: \"Linguagem, Compose compiler e serialization\",\n        initials: \"KT\"\n      )\n\n      Item(\n        title: \"Activity Compose 1.11.0\",\n        subtitle: \"Ponte entre Activity e Compose\",\n        initials: \"AC\"\n      )\n\n      Item(\n        title: \"Navigation Compose 2.9.3\",\n        subtitle: \"Pilha de telas e modais\",\n        initials: \"NC\"\n      )\n\n      Item(\n        title: \"NShiftUI-Android\",\n        subtitle: \"Engine SDUI distribuída como AAR\",\n        initials: \"NS\"\n      )\n\n      Item(\n        title: \"RainbowParser 0.1.0-beta.1\",\n        subtitle: \"Parser da linguagem Rainbow\",\n        initials: \"RP\"\n      )\n\n      Item(\n        title: \"nshiftui-ksp 0.2.0-beta.1\",\n        subtitle: \"Geração do catálogo de plugins e eventos\",\n        initials: \"KS\"\n      )\n\n      Item(\n        title: \"Koin 4.1.0\",\n        subtitle: \"Injeção de dependências\",\n        initials: \"KO\"\n      )\n\n      Item(\n        title: \"OkHttp 4.12.0\",\n        subtitle: \"Requisições HTTP\",\n        initials: \"OK\"\n      )\n\n      Item(\n        title: \"kotlinx.serialization 1.9.0\",\n        subtitle: \"Metadata dos plugins em JSON\",\n        initials: \"KX\"\n      )\n\n      Item(\n        title: \"Android WebView\",\n        subtitle: \"Página do container WebView\",\n        initials: \"WV\"\n      )\n    }\n\n    Text(\n      text: \"WEB · CMS\",\n      style: \"xs\",\n      weight: \"semibold\",\n      color: \"primary\"\n    )\n\n    Card {\n      Item(\n        title: \"React 19.3\",\n        subtitle: \"Interface do editor\",\n        initials: \"RE\"\n      )\n\n      Item(\n        title: \"Vite 8.3 e TypeScript 6.0\",\n        subtitle: \"Build e tipagem\",\n        initials: \"VT\"\n      )\n\n      Item(\n        title: \"Tailwind CSS 4.3\",\n        subtitle: \"Estilos\",\n        initials: \"TW\"\n      )\n\n      Item(\n        title: \"shadcn 4.21, Radix UI e Base UI\",\n        subtitle: \"Componentes do editor\",\n        initials: \"SC\"\n      )\n\n      Item(\n        title: \"TanStack Router, Query e Table\",\n        subtitle: \"Rotas, dados e tabelas\",\n        initials: \"TS\"\n      )\n\n      Item(\n        title: \"React Flow 12.12\",\n        subtitle: \"Canvas de fluxo de eventos\",\n        initials: \"RF\"\n      )\n\n      Item(\n        title: \"rainbow-parser-wasm-web\",\n        subtitle: \"Parser Rainbow em WebAssembly\",\n        initials: \"WA\"\n      )\n\n      Item(\n        title: \"Zod 4.6 e Zustand 5.0\",\n        subtitle: \"Validação e estado\",\n        initials: \"ZZ\"\n      )\n\n      Item(\n        title: \"Sonner 2.0 e Lucide React\",\n        subtitle: \"Toasts e ícones\",\n        initials: \"SL\"\n      )\n    }\n\n    Text(\n      text: \"BACKEND\",\n      style: \"xs\",\n      weight: \"semibold\",\n      color: \"primary\"\n    )\n\n    Card {\n      Item(\n        title: \"Fastify 5.6\",\n        subtitle: \"API HTTP com Swagger\",\n        initials: \"FY\"\n      )\n\n      Item(\n        title: \"PostgreSQL (postgres 3.4)\",\n        subtitle: \"Telas, versões e auditoria\",\n        initials: \"PG\"\n      )\n\n      Item(\n        title: \"rainbow-parser-wasm-node\",\n        subtitle: \"Validação Rainbow no servidor\",\n        initials: \"WA\"\n      )\n\n      Item(\n        title: \"Zod 4.1\",\n        subtitle: \"Validação das requisições\",\n        initials: \"ZD\"\n      )\n    }\n\n    Text(\n      text: \"APIS DA DEMO\",\n      style: \"xs\",\n      weight: \"semibold\",\n      color: \"primary\"\n    )\n\n    Card {\n      Item(\n        title: \"PokeAPI\",\n        subtitle: \"Pokédex e detalhes\",\n        initials: \"PK\"\n      )\n\n      Item(\n        title: \"DummyJSON\",\n        subtitle: \"Produtos da Loja\",\n        initials: \"DJ\"\n      )\n    }\n  }\n}"
