  {
    "id": "60dc7e48-1cbf-4117-a443-a5d635a775e4",
    "name": "settings",
    "is_root": false,
    "version": "1.0.7",
    "revision": 8,
    "created_at": "2026-11-21T18:55:31.942085+00:00",
    "updated_at": "2026-11-22T22:29:12.904361+00:00",
    "description": "Configurações do aplicativo. O tema escolhido vale para todas as telas.",
    "rainbow_source": "use Screen@1.0.0\nuse VerticalStack@1.0.0\nuse HorizontalStack@1.0.0\nuse Text@1.0.0\nuse Badge@1.0.0\nuse Avatar@1.0.0\nuse Card@1.0.0\nuse Button@1.0.0\nuse Select@1.0.0\nuse Item@1.0.0\nuse Progress@1.0.0\nuse Alert@1.0.0\nuse Sheet@1.0.0\nuse ChangeDSTheme@1.0.0\nuse OpenBottomSheetEvent@1.0.0\nuse CloseBottomSheetEvent@1.0.0\nuse CloseAppEvent@1.0.0\nuse NavigateEvent@1.0.0\n\nScreen(\n  navigationBar: (\n    title: \"Ajustes\",\n    leading: \"auto\"\n  ),\n  scroll: (\n    enabled: true,\n    fastRefresh: true\n  )\n) {\n  VerticalStack(\n    alignment: .leading,\n    spacing: 16\n  ) {\n    Card {\n      HorizontalStack(\n        alignment: .center,\n        spacing: 16\n      ) {\n        Avatar(\n          initials: \"NS\",\n          size: \"lg\"\n        )\n\n        VerticalStack(\n          alignment: .leading,\n          spacing: 4\n        ) {\n          Text(\n            text: \"NShiftUI Showcase\",\n            style: \"lg\",\n            weight: \"semibold\",\n            color: \"foreground\"\n          )\n\n          Text(\n            text: \"Demo de SDUI com Rainbow e CMS\",\n            style: \"sm\",\n            weight: \"regular\",\n            color: \"mutedForeground\"\n          )\n        }\n      }\n\n      HorizontalStack(\n        alignment: .center,\n        spacing: 8\n      ) {\n        Badge(\n          text: \"iOS\",\n          variant: \"default\"\n        )\n\n        Badge(\n          text: \"Android\",\n          variant: \"secondary\"\n        )\n\n        Badge(\n          text: \"CMS\",\n          variant: \"outline\"\n        )\n      }\n    }\n\n    Text(\n      text: \"APARÊNCIA\",\n      style: \"xs\",\n      weight: \"semibold\",\n      color: \"primary\"\n    )\n\n    Card {\n      Text(\n        text: \"Tema do aplicativo\",\n        style: \"base\",\n        weight: \"semibold\",\n        color: \"foreground\"\n      )\n\n      Text(\n        text: \"Troca as cores de todas as telas na hora, sem publicar uma nova versão.\",\n        style: \"sm\",\n        weight: \"regular\",\n        color: \"mutedForeground\"\n      )\n\n      Select(\n        options: [\"Neutral\", \"Stone\", \"Zinc\", \"Mauve\", \"Olive\", \"Mist\", \"Taupe\", \"Amber\", \"Blue\", \"Cyan\", \"Emerald\", \"Fuchsia\", \"Green\", \"Indigo\", \"Lime\", \"Orange\", \"Pink\", \"Purple\", \"Red\", \"Rose\", \"Sky\", \"Teal\", \"Violet\", \"Yellow\"],\n        selection: \"Neutral\"\n      )\n      .events {\n        OnSelect {\n          ChangeDSTheme()\n        }\n      }\n    }\n\n    Text(\n      text: \"SOBRE A DEMO\",\n      style: \"xs\",\n      weight: \"semibold\",\n      color: \"primary\"\n    )\n\n    Card {\n      Item(\n        title: \"Versão do app\",\n        subtitle: \"0.1.0 · iOS e Android\",\n        initials: \"V1\"\n      )\n\n      Text(\n        text: \"Telas servidas pelo CMS\",\n        style: \"base\",\n        weight: \"semibold\",\n        color: \"foreground\"\n      )\n\n      Progress(value: 1.0)\n\n      Text(\n        text: \"Início, Pokédex, Loja, Carrinho, Detalhes, Ajustes, Documentação e Referências são publicados como Rainbow.\",\n        style: \"sm\",\n        weight: \"regular\",\n        color: \"mutedForeground\"\n      )\n    }\n\n    Text(\n      text: \"RECURSOS\",\n      style: \"xs\",\n      weight: \"semibold\",\n      color: \"primary\"\n    )\n\n    Card {\n      Text(\n        text: \"Conheça o NShiftUI\",\n        style: \"base\",\n        weight: \"semibold\",\n        color: \"foreground\"\n      )\n\n      Text(\n        text: \"A documentação abre numa WebView servida pelo CMS; as referências listam os SDKs da POC.\",\n        style: \"sm\",\n        weight: \"regular\",\n        color: \"mutedForeground\"\n      )\n\n      Button(\n        title: \"Documentação do NShiftUI\",\n        icon: \"book-open\",\n        variant: \"default\",\n        size: \"default\",\n        isEnabled: true\n      )\n      .events {\n        OnTap {\n          NavigateEvent(screenName: \"docs\")\n        }\n      }\n\n      Button(\n        title: \"Referências, inspirações e SDKs\",\n        icon: \"library\",\n        variant: \"outline\",\n        size: \"default\",\n        isEnabled: true\n      )\n      .events {\n        OnTap {\n          NavigateEvent(screenName: \"references\")\n        }\n      }\n    }\n\n    Alert(\n      title: \"Tudo dinâmico\",\n      message: \"Esta tela inteira vem do CMS. Edite-a no editor e veja a mudança no próximo carregamento.\",\n      variant: \"default\"\n    )\n\n    Button(\n      title: \"Como esta tela é feita\",\n      icon: \"\",\n      variant: \"outline\",\n      size: \"default\",\n      isEnabled: true\n    )\n    .events {\n      OnTap {\n        OpenBottomSheetEvent(sheetID: \"settings-info\")\n      }\n    }\n\n    Button(\n      title: \"Fechar o app\",\n      icon: \"\",\n      variant: \"destructive\",\n      size: \"default\",\n      isEnabled: true\n    )\n    .events {\n      OnTap {\n        CloseAppEvent()\n      }\n    }\n  }\n}\n.slots {\n  BottomSheet {\n    Sheet(title: \"Ajustes em Rainbow\") {\n      Text(\n        text: \"Cada seção é um Card com plugins do design system: Avatar, Badge, Select, Item, Progress e Alert.\",\n        style: \"base\",\n        weight: \"regular\",\n        color: \"foreground\"\n      )\n\n      Text(\n        text: \"O tema usa o evento ChangeDSTheme e o botão de fechar usa o CloseAppEvent; nenhum componente tem regra de negócio no app.\",\n        style: \"sm\",\n        weight: \"regular\",\n        color: \"mutedForeground\"\n      )\n\n      Button(\n        title: \"Fechar\",\n        icon: \"\",\n        variant: \"secondary\",\n        size: \"default\",\n        isEnabled: true\n      )\n      .events {\n        OnTap {\n          CloseBottomSheetEvent(sheetID: \"settings-info\")\n        }\n      }\n    }\n    .id(\"settings-info\")\n  }\n}"
  }
]
$screen_snapshot$::jsonb)
    returning *
  )
  insert into screen_versions (
    screen_id, version, rainbow_source, created_at, name, description, is_root
  )
  select id, version, rainbow_source, updated_at, name, description, is_root
  from seeded;
end;
